import referencePoints from "../data/sites.json";
import type { LandingSite } from "./types";

/** NASA LOLA DEM center pixels, not NASA-selected landing coordinates.
 * Generated by scripts/refresh-nasa-data.py; each record retains provenance.
 * MOON_ME_DE421, east-positive longitude, height above the 1737.4 km sphere.
 * Horizons uses that same spherical lunar observer model.
 */
export const LANDING_SITES: LandingSite[] = referencePoints;

export function getSiteById(id: string): LandingSite | undefined {
  return LANDING_SITES.find((site) => site.id === id);
}

export function getDefaultSites(): { siteA: LandingSite; siteB: LandingSite } {
  return { siteA: LANDING_SITES[0], siteB: LANDING_SITES[3] };
}
